	if slide.Role == RoleSection && slide.Sectioned {
		b.WriteString("## " + heading + "\n\n")
		return
	}
	b.WriteString("### " + heading + "\n\n")

	if lead := strings.TrimSpace(slide.Lead); lead != "" && lead != heading {
